for _language, _row in _HOLLOW_UI_ROWS.items():
    _parts = _row.split('|')
    UI_TRANSLATIONS.setdefault(_language, {}).update(zip(_HOLLOW_UI_KEYS, _parts[:7], strict=True))
    for _divisor in (2, 4, 8):
        UI_TRANSLATIONS[_language][f'Voxel size = cavity inset / {_divisor}'] = _parts[7] + str(_divisor)
